// Bundles the hook entrypoint into ONE self-contained CJS file: the engine's own
// source plus @babel/parser, the only runtime dependency. The bundle is readable
// (not minified), so anyone, and the plugin directory's validator, can inspect
// exactly what runs on every edit: dist/check.js is the entire shipped artifact.
import { statSync } from "node:fs";
import { build } from "esbuild";

const BANNER = `// ts-patterns engine: the rules in engine/src plus @babel/parser (MIT; see THIRD_PARTY_NOTICES.md).
// Generated by engine/build.mjs from the sources in this repository; CI rebuilds it and fails
// if this file differs. Readable on purpose, not minified. Read engine/src to change it.`;

await build({
  entryPoints: ["src/check.ts"],
  bundle: true,
  platform: "node",
  format: "cjs",
  target: "node18",
  outfile: "dist/check.js",
  banner: { js: BANNER },
  legalComments: "inline",
  logLevel: "info",
});

// The plugin directory rejects any file over 5 MiB. This bundle is under 1 MiB, so
// a jump toward the limit means something unexpected was pulled in.
const MAX_BYTES = 5 * 1024 * 1024;
const size = statSync("dist/check.js").size;
if (size > MAX_BYTES) {
  throw new Error(`dist/check.js is ${(size / 1048576).toFixed(2)} MiB; the plugin directory rejects files over 5 MiB`);
}
